<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { Info, Pause, Play, Search, X } from '@lucide/vue'
import { createIntradayItems, type IntradayItem } from './intraday.data'
import IntradayChart from './IntradayChart.vue'

const data = reactive(createIntradayItems())
const period = ref<14 | 70 | 140>(70)
const universe = ref<'overview' | 'sp1500'>('overview')
const view = ref<'cards' | 'table'>('cards')
const query = ref('')
const playing = ref(true)
const tick = ref(0)
const detail = ref<IntradayItem | null>(null)
let timer: ReturnType<typeof setInterval> | null = null
const periodName = computed(() => ({ 14: '1D', 70: '1W', 140: '2W' })[period.value])
const visible = computed(() => data[universe.value].filter((item) => `${item.name} ${item.description}`.toLowerCase().includes(query.value.trim().toLowerCase())))
const demoTime = (value: number) => { const seconds = 16 * 3600 + value * 4; return [Math.floor(seconds / 3600) % 24, Math.floor(seconds / 60) % 60, seconds % 60].map((part) => String(part).padStart(2, '0')).join(':') }
const number = (item: IntradayItem) => item.values.at(-1)!.toLocaleString('en-US', { minimumFractionDigits: item.decimals, maximumFractionDigits: item.decimals })
const changeText = (item: IntradayItem) => `${item.change > 0 ? '+' : ''}${item.change.toLocaleString('en-US', { minimumFractionDigits: item.decimals, maximumFractionDigits: item.decimals })}${item.unit === '%' ? ' pp' : ''}`
const referenceText = (item: IntradayItem) => item.min === 0 && item.max === 100 ? '30 / 70 reference lines' : item.zeroBaseline ? 'Zero reference line' : item.unit === 'x' ? '1.00 ratio reference' : 'Illustrative reading'
const changeClass = (item: IntradayItem) => item.change > 0 ? 'text-[var(--app-positive)]' : item.change < 0 ? 'text-[var(--app-negative)]' : 'text-[var(--app-text-muted)]'
function points(item: IntradayItem, height = 40) {
  const values = item.values.slice(-period.value), min = Math.min(...values), max = Math.max(...values), span = max - min || 1
  return values.map((value, index) => `${index / Math.max(values.length - 1, 1) * 100},${height - 3 - (value - min) / span * (height - 6)}`).join(' ')
}
function update() {
  if (!playing.value || document.hidden) return
  tick.value++
  data.all.forEach((item, index) => {
    if (item.group !== 'index' && (index + tick.value) % 3 !== 0) return
    const precision = 10 ** item.decimals, step = 1 / precision, amplitude = Math.max(step, (item.max - item.min) * .0015)
    const motion = (Math.sin(tick.value * 1.87 + index * 2.17) + .45 * Math.sin(tick.value * .43 + index)) * amplitude
    const previous = item.values[item.values.length - 1]
    const next = Math.max(item.min, Math.min(item.max, Math.round((previous + motion + (item.anchor - previous) * .08) * precision) / precision))
    if (next === previous) return
    item.values[item.values.length - 1] = next
    item.change = Number((next - previous).toFixed(item.decimals))
    item.updated = tick.value
  })
}
function start() { if (!timer && playing.value) timer = setInterval(update, 4000) }
function stop() { if (timer) clearInterval(timer); timer = null }
function toggle() { playing.value = !playing.value; if (playing.value) start(); else stop() }
function visibility() { if (document.hidden) stop(); else start() }
onMounted(() => { document.addEventListener('visibilitychange', visibility); start() })
onBeforeUnmount(() => { stop(); document.removeEventListener('visibilitychange', visibility) })
</script>

<template>
  <section class="space-y-4" data-testid="intraday-monitor-content">
    <div class="flex items-start gap-3 rounded-lg border border-[var(--app-border)] bg-[var(--app-primary-soft)] px-4 py-3 text-xs leading-5 text-[var(--app-text-secondary)]"><Info :size="18" class="mt-0.5 shrink-0 text-[var(--app-primary)]" /><p><strong>Illustrative data.</strong> The 4-second demo refresh revises the current snapshot; historical observations remain 30 minutes apart.</p></div>
    <div class="flex flex-wrap items-center justify-between gap-4"><div class="flex items-center gap-2 text-xs"><span class="font-semibold text-[var(--app-text-muted)]">Chart window</span><div class="inline-flex rounded-md border border-[var(--app-border)] bg-[var(--app-surface-soft)] p-0.5" role="group" aria-label="Chart window"><button v-for="option in [{value:14,label:'1D'},{value:70,label:'1W'},{value:140,label:'2W'}] as const" :key="option.value" type="button" :aria-pressed="period === option.value" class="rounded px-3 py-1.5 font-semibold" :class="period === option.value ? 'bg-[var(--app-surface)] text-[var(--app-primary)] shadow-sm' : 'text-[var(--app-text-muted)]'" @click="period = option.value">{{ option.label }}</button></div></div><div class="flex flex-wrap items-center gap-3 text-xs"><span class="inline-flex items-center gap-1.5 text-[var(--app-text-secondary)]"><i class="h-2 w-2 rounded-full" :class="playing ? 'bg-[var(--app-positive)]' : 'bg-[var(--app-text-muted)]'" />{{ playing ? 'Demo updates · every 4s' : 'Demo updates paused' }}</span><span class="text-[var(--app-text-muted)]">Last update <b class="text-[var(--app-text-secondary)]">{{ demoTime(tick) }}</b> demo time</span><button type="button" :aria-label="playing ? 'Pause demo updates' : 'Resume demo updates'" :aria-pressed="playing" class="inline-flex h-8 items-center gap-1.5 rounded-md border border-[var(--app-border)] bg-[var(--app-surface)] px-3 font-semibold text-[var(--app-text-secondary)]" @click="toggle"><Pause v-if="playing" :size="13" /><Play v-else :size="13" />{{ playing ? 'Pause' : 'Resume' }}</button></div></div>
    <div class="flex flex-wrap justify-between gap-2 text-[11px] text-[var(--app-text-muted)]"><span><strong class="text-[var(--app-text-secondary)]">Snapshot date: 27 Oct 2026</strong> · 16:00 ET</span><span>Illustrative data · {{ period }} half-hour observations in the selected chart window</span></div>
    <div class="grid gap-3 md:grid-cols-3"><article v-for="item in data.indexes" :key="item.id" class="rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] p-4 shadow-sm"><header class="flex items-center justify-between gap-2"><h2 class="text-sm font-semibold">{{ item.name }}</h2><button type="button" :aria-label="`Expand ${item.name} chart`" class="h-7 w-7 rounded border border-[var(--app-border)] text-[var(--app-text-muted)] hover:text-[var(--app-primary)]" @click="detail = item">↗</button></header><div class="mt-3 grid grid-cols-[minmax(0,1fr)_40%] items-end gap-3"><div><strong class="text-3xl font-semibold tabular-nums">{{ number(item) }}</strong><small class="ml-1 text-[10px] text-[var(--app-text-muted)]">{{ item.unit }}</small><p class="mt-1 text-xs" :class="changeClass(item)">{{ changeText(item) }} <small class="text-[var(--app-text-muted)]">Δ since previous update</small></p></div><button type="button" :aria-label="`View ${item.name} recent trend`" class="w-full" @click="detail = item"><svg viewBox="0 0 100 49" preserveAspectRatio="none" class="h-[49px] w-full"><polyline :points="points(item,49)" fill="none" stroke="var(--app-primary)" stroke-width="1.6" vector-effect="non-scaling-stroke" /></svg></button></div><footer class="mt-3 flex justify-between border-t border-[var(--app-border-muted)] pt-2 text-[10px] text-[var(--app-text-muted)]"><span>Index level · demo</span><span>{{ periodName }} trend · {{ demoTime(item.updated) }}</span></footer></article></div>
    <div class="flex flex-wrap items-end justify-between gap-3"><div><h2 class="font-semibold">{{ universe === 'overview' ? 'Indicator overview' : 'S&P 1500 indicators' }}</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">{{ universe === 'overview' ? 'Models, participation, momentum and options in one view.' : 'Example participation, volume and momentum measures for the broad market.' }}</p></div><span class="rounded bg-[var(--app-surface-muted)] px-2 py-1 text-xs text-[var(--app-text-muted)]">{{ visible.length }} indicators</span></div>
    <div class="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--app-border)]"><div class="flex gap-5" role="tablist" aria-label="Intraday indicator universe"><button v-for="option in [{value:'overview',label:'Overview',count:16},{value:'sp1500',label:'S&P 1500',count:8}] as const" :key="option.value" type="button" role="tab" :aria-selected="universe === option.value" class="border-b-2 pb-3 text-xs font-semibold" :class="universe === option.value ? 'border-[var(--app-primary)] text-[var(--app-primary)]' : 'border-transparent text-[var(--app-text-muted)]'" @click="universe = option.value">{{ option.label }} <small>{{ option.count }}</small></button></div><div class="flex items-center gap-2 pb-2"><label class="flex h-8 items-center gap-2 rounded border border-[var(--app-border)] bg-[var(--app-surface)] px-2"><Search :size="14" class="text-[var(--app-text-muted)]" /><input v-model="query" type="search" aria-label="Search indicators" placeholder="Search indicators…" class="w-36 bg-transparent text-xs outline-none" /></label><div class="inline-flex rounded border border-[var(--app-border)] p-0.5" role="group" aria-label="Indicator display"><button v-for="option in ['cards','table'] as const" :key="option" type="button" :aria-pressed="view === option" class="rounded px-2 py-1 text-xs capitalize" :class="view === option ? 'bg-[var(--app-primary-soft)] font-semibold text-[var(--app-primary)]' : 'text-[var(--app-text-muted)]'" @click="view = option">{{ option }}</button></div></div></div>
    <p class="text-xs text-[var(--app-text-muted)]"><strong>Δ since previous update.</strong> Percentages change in percentage points (pp); other readings keep their own units. Only changed values briefly highlight.</p>
    <div v-if="!visible.length" class="rounded-lg border border-dashed border-[var(--app-border)] bg-[var(--app-surface)] p-8 text-center text-xs text-[var(--app-text-muted)]"><strong class="block text-sm">No matching indicators</strong><p class="mt-2">Try another name or clear your search to see this category.</p><button type="button" class="mt-3 rounded border border-[var(--app-border)] px-3 py-2 text-[var(--app-primary)]" @click="query = ''">Clear search</button></div>
    <div v-else-if="view === 'cards'" class="grid gap-4 md:grid-cols-2 2xl:grid-cols-3"><article v-for="item in visible" :key="item.id" class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] shadow-sm"><header class="flex items-start justify-between gap-2 px-4 pt-4"><div><button type="button" class="text-left text-xs font-semibold text-[var(--app-text-secondary)] hover:text-[var(--app-primary)]" @click="detail = item">{{ item.name }}</button><p class="mt-1 text-[10px] text-[var(--app-text-muted)]">{{ item.description }}</p></div><button type="button" :aria-label="`Expand ${item.name} chart`" class="h-7 w-7 shrink-0 rounded border border-[var(--app-border)] text-[var(--app-text-muted)]" @click="detail = item">↗</button></header><div class="flex items-baseline justify-between gap-2 px-4 pt-3"><strong class="text-2xl tabular-nums">{{ number(item) }} <small class="text-xs font-normal text-[var(--app-text-muted)]">{{ item.unit }}</small></strong><span class="text-xs tabular-nums" :class="changeClass(item)">{{ changeText(item) }}</span></div><div class="px-2"><IntradayChart :item="item" :period="period" /></div><footer class="flex justify-between gap-2 border-t border-[var(--app-border)] bg-[var(--app-surface-soft)] px-4 py-2 text-[10px] text-[var(--app-text-muted)]"><span>{{ referenceText(item) }}</span><span>Updated {{ demoTime(item.updated) }}</span></footer></article></div>
    <section v-else class="overflow-x-auto rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)]"><table class="w-full min-w-[800px] text-left text-xs"><thead class="bg-[var(--app-surface-muted)] text-[var(--app-text-muted)]"><tr><th v-for="heading in ['Indicator','Current','Change Δ','Recent trend','Updated']" :key="heading" class="px-4 py-3">{{ heading }}</th></tr></thead><tbody><tr v-for="item in visible" :key="item.id" class="border-t border-[var(--app-border-muted)] hover:bg-[var(--app-surface-hover)]"><td class="px-4 py-3"><button type="button" class="font-semibold text-[var(--app-text-secondary)] hover:text-[var(--app-primary)]" @click="detail = item">{{ item.name }}</button><small class="block text-[var(--app-text-muted)]">{{ item.description }}</small></td><td class="px-4 py-3 font-semibold tabular-nums">{{ number(item) }} <small>{{ item.unit }}</small></td><td class="px-4 py-3 tabular-nums" :class="changeClass(item)">{{ changeText(item) }}</td><td class="w-[170px] px-4 py-3"><button type="button" :aria-label="`Expand ${item.name} recent trend`" class="w-full" @click="detail = item"><svg viewBox="0 0 100 35" preserveAspectRatio="none" class="h-[35px] w-full"><polyline :points="points(item,35)" fill="none" stroke="var(--app-primary)" stroke-width="1.5" vector-effect="non-scaling-stroke" /></svg></button></td><td class="px-4 py-3 text-[var(--app-text-muted)]">{{ demoTime(item.updated) }} <small class="block">Demo time</small></td></tr></tbody></table></section>
    <p class="text-xs leading-5 text-[var(--app-text-muted)]">Demo timing: the last historical snapshot is 16:00 ET on 27 Oct 2026. Each refresh revises that snapshot’s current reading; “Updated” uses an accelerated demo clock. Reference lines are illustrative. Select any indicator to inspect its chart.</p>
    <Teleport to="body"><div v-if="detail" class="fixed inset-0 z-[80] grid place-items-center bg-[var(--app-overlay)] p-4" role="dialog" aria-modal="true" :aria-label="`${detail.name} detail`"><section class="w-full max-w-4xl rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] p-5 shadow-2xl"><header class="mb-4 flex justify-between gap-3"><div><h2 class="text-lg font-semibold">{{ detail.name }}</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">{{ detail.description }} · {{ periodName }} window</p></div><button type="button" aria-label="Close detail" @click="detail = null"><X :size="18" /></button></header><div class="mb-3 flex items-baseline gap-3"><strong class="text-2xl">{{ number(detail) }} <small class="text-xs font-normal">{{ detail.unit }}</small></strong><span class="text-xs" :class="changeClass(detail)">{{ changeText(detail) }}</span></div><IntradayChart :item="detail" :period="period" :height="300" /><p class="mt-3 text-xs text-[var(--app-text-muted)]">{{ referenceText(detail) }} · Updated {{ demoTime(detail.updated) }} demo time</p></section></div></Teleport>
  </section>
</template>
